package org.sleepwell.app;
import android.content.Context;import android.os.Looper;import androidx.health.connect.client.*;import androidx.health.connect.client.records.*;import androidx.health.connect.client.records.metadata.Metadata;import androidx.health.connect.client.request.*;import androidx.health.connect.client.response.*;import androidx.health.connect.client.changes.*;import androidx.health.connect.client.time.TimeRangeFilter;import kotlin.coroutines.*;import java.time.*;import java.util.*;import java.util.concurrent.*;
/** Official Jetpack adapter. Only the owned manual-sync worker may wait for suspend results. */
final class HealthSleepAndroid implements HealthSleepPort {
 final Context app;HealthSleepAndroid(Context context){app=context.getApplicationContext();}
 interface Call<T>{Object invoke(Continuation<? super T> continuation);}
 static <T>T await(Call<T> call)throws Exception{if(Looper.myLooper()==Looper.getMainLooper())throw new IllegalStateException("Health Connect work must run off the UI thread.");CompletableFuture<T> future=new CompletableFuture<>();Object immediate=call.invoke(new Continuation<T>(){public CoroutineContext getContext(){return EmptyCoroutineContext.INSTANCE;}@SuppressWarnings("unchecked")public void resumeWith(Object result){try{kotlin.ResultKt.throwOnFailure(result);future.complete((T)result);}catch(Throwable error){future.completeExceptionally(error);}}});if(immediate!=kotlin.coroutines.intrinsics.IntrinsicsKt.getCOROUTINE_SUSPENDED()){@SuppressWarnings("unchecked")T result=(T)immediate;return result;}try{return future.get(45,TimeUnit.SECONDS);}catch(ExecutionException e){if(e.getCause() instanceof Exception)throw(Exception)e.getCause();throw new IllegalStateException("Health Connect could not complete this operation.",e.getCause());}catch(TimeoutException timeout){throw new IllegalStateException("Health Connect did not respond. Completed provider writes may remain; retry is safe.",timeout);}}
 HealthConnectClient client(){return HealthConnectClient.getOrCreate(app);}
 void require(String permission)throws Exception{Access status=access();if(!status.available()||!status.granted.contains(permission))throw new SecurityException("Sleep access changed. Review Health Connect permissions.");}
 public Access access()throws Exception{int status=HealthConnectClient.getSdkStatus(app);Set<String> granted=status==HealthConnectClient.SDK_AVAILABLE?await(done->client().getPermissionController().getGrantedPermissions(done)):Set.of();return new Access(status,granted);}
 static kotlin.reflect.KClass<SleepSessionRecord> type(){return kotlin.jvm.JvmClassMappingKt.getKotlinClass(SleepSessionRecord.class);}
 public String token()throws Exception{require(READ);return await(done->client().getChangesToken(new ChangesTokenRequest(Set.of(type()),Set.of()),done));}
 public Page read(long start,long end,String page)throws Exception{require(READ);ReadRecordsResponse<SleepSessionRecord> response=await(done->client().readRecords(new ReadRecordsRequest<>(type(),TimeRangeFilter.between(Instant.ofEpochMilli(start),Instant.ofEpochMilli(end)),Set.of(),true,200,page),done));List<HealthSleep> records=new ArrayList<>();for(SleepSessionRecord r:response.getRecords())records.add(from(r));return new Page(records,response.getPageToken());}
 public Changes changes(String token)throws Exception{require(READ);ChangesResponse response=await(done->client().getChanges(token,done));List<HealthSleep> records=new ArrayList<>();List<String> deleted=new ArrayList<>();for(Change change:response.getChanges()){if(change instanceof DeletionChange)deleted.add(((DeletionChange)change).getRecordId());else if(change instanceof UpsertionChange&&((UpsertionChange)change).getRecord() instanceof SleepSessionRecord)records.add(from((SleepSessionRecord)((UpsertionChange)change).getRecord()));}return new Changes(records,deleted,response.getNextChangesToken(),response.hasMore(),response.getChangesTokenExpired());}
 static HealthSleep from(SleepSessionRecord r){List<HealthSleep.Stage> stages=new ArrayList<>();for(SleepSessionRecord.Stage s:r.getStages())stages.add(new HealthSleep.Stage(s.getStartTime().toEpochMilli(),s.getEndTime().toEpochMilli(),s.getStage()));return new HealthSleep(r.getMetadata().getId(),r.getMetadata().getDataOrigin().getPackageName(),r.getStartTime().toEpochMilli(),r.getEndTime().toEpochMilli(),r.getMetadata().getLastModifiedTime().toEpochMilli(),r.getStartZoneOffset()==null?null:r.getStartZoneOffset().getTotalSeconds(),r.getEndZoneOffset()==null?null:r.getEndZoneOffset().getTotalSeconds(),r.getTitle()==null?"":r.getTitle(),r.getNotes()==null?"":r.getNotes(),stages);}
 public String insert(String client,long version,HealthSleep sleep,boolean manual)throws Exception{require(WRITE);List<SleepSessionRecord.Stage> stages=new ArrayList<>();for(HealthSleep.Stage s:sleep.stages)stages.add(new SleepSessionRecord.Stage(Instant.ofEpochMilli(s.start),Instant.ofEpochMilli(s.end),s.kind));Metadata metadata=manual?Metadata.manualEntry(client,version):Metadata.activelyRecorded(new androidx.health.connect.client.records.metadata.Device(androidx.health.connect.client.records.metadata.Device.TYPE_PHONE,android.os.Build.MANUFACTURER,android.os.Build.MODEL),client,version);SleepSessionRecord record=new SleepSessionRecord(Instant.ofEpochMilli(sleep.start),sleep.startOffset==null?null:ZoneOffset.ofTotalSeconds(sleep.startOffset),Instant.ofEpochMilli(sleep.end),sleep.endOffset==null?null:ZoneOffset.ofTotalSeconds(sleep.endOffset),metadata,sleep.title,sleep.notes,stages);InsertRecordsResponse result=await(done->client().insertRecords(List.of(record),done));if(result.getRecordIdsList().size()!=1)throw new IllegalStateException("Health Connect did not acknowledge the sleep export.");return result.getRecordIdsList().get(0);}
 public void delete(String client)throws Exception{require(WRITE);HealthSleepAndroid.<kotlin.Unit>await(done->client().deleteRecords(type(),List.of(),List.of(client),done));}
}
